package com.shopsphere;import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.util.UUID;import org.junit.jupiter.api.*;class CartServiceTest{CartService service;UUID user,product;@BeforeEach void set(){user=UUID.randomUUID();product=UUID.randomUUID();service=new CartService(new CartRepository.InMemory(),id->new ProductPricingGateway.Snapshot(id,"Nova","/nova.jpg",BigDecimal.valueOf(100)));}@Test void addUpdateRemoveCalculatesTotals(){Cart added=service.add(user,product,2);assertEquals(BigDecimal.valueOf(200),added.subtotal());assertEquals(2,added.itemCount());Cart updated=service.update(user,product,4);assertEquals(BigDecimal.valueOf(400),updated.subtotal());assertTrue(service.remove(user,product).items().isEmpty());}@Test void ignoresClientPriceByDesign(){Cart c=service.add(user,product,1);assertEquals(BigDecimal.valueOf(100),c.items().getFirst().unitPrice());}}
